'use client';

/**
 * Overview Industry — Trade flows — FIGARO dataset access layer.
 * --------------------------------------------------------------
 * Types, loaders and aggregation helpers for the repo-hosted FIGARO extract
 * (`public/data/figaro/*.json`, regenerated by
 * `scripts/fetch-figaro-io-dataset.mjs` from Eurostat `naio_10_fcp_ii4`).
 * The data is served from the MethodHub itself — the client fetches the JSON
 * once and every view (table viewer, analysis dashboard) derives from it.
 */

export const FIGARO_DATASET_URL =
  'https://ec.europa.eu/eurostat/databrowser/view/naio_10_fcp_ii4/default/table?lang=en';
export const IO_JSON_PATH = '/data/figaro/figaro-io-eu27.json';
export const GLOBAL_JSON_PATH = '/data/figaro/figaro-global-flows.json';

export const FIGARO_MATRIX_YEARS = ['2022', '2023'] as const;
export type FigaroYear = (typeof FIGARO_MATRIX_YEARS)[number];

export interface FigaroIoData {
  meta: { dataset: string; title: string; source: string; unit: string; years: string[]; generated: string; note: string };
  /** Code → English label, for industries, VA rows and final-demand columns. */
  industries: Record<string, string>;
  /** Country code → English name. */
  countries: Record<string, string>;
  /** Row axis: 64 industries + 6 value-added/adjustment rows. */
  indAva: string[];
  /** Column axis: 64 industries + 5 final-demand categories. */
  indUse: string[];
  nIndustries: number;
  /** 'EU27' (intra-EU incl. VA rows) + 23 extra-EU partner areas. */
  origins: string[];
  /** matrix[year][origin][rowIdx][colIdx], € million. */
  matrix: Record<FigaroYear, Record<string, number[][]>>;
}

export interface FigaroGlobalData {
  meta: { dataset: string; source: string; unit: string; years: string[]; generated: string; note: string };
  countries: string[];
  countryNames: Record<string, string>;
  euMembers: string[];
  extra: string[];
  industries: string[];
  /** countryFlows[year].int|fin[origIdx][destIdx], € million. */
  countryFlows: Record<FigaroYear, { int: number[][]; fin: number[][] }>;
  /** euExportsByIndustry[year].int|fin[industryIdx][extraDestIdx], € million. */
  euExportsByIndustry: Record<FigaroYear, { int: number[][]; fin: number[][] }>;
}

let ioPromise: Promise<FigaroIoData> | null = null;
let globalPromise: Promise<FigaroGlobalData> | null = null;

export function loadFigaroIo(): Promise<FigaroIoData> {
  if (!ioPromise) {
    ioPromise = fetch(IO_JSON_PATH).then((r) => {
      if (!r.ok) throw new Error(`Failed to load ${IO_JSON_PATH} (HTTP ${r.status})`);
      return r.json();
    });
  }
  return ioPromise;
}

export function loadFigaroGlobal(): Promise<FigaroGlobalData> {
  if (!globalPromise) {
    globalPromise = fetch(GLOBAL_JSON_PATH).then((r) => {
      if (!r.ok) throw new Error(`Failed to load ${GLOBAL_JSON_PATH} (HTTP ${r.status})`);
      return r.json();
    });
  }
  return globalPromise;
}

/* ------------------------------------------------------------- classification */

/** NACE section letter of an A*64 industry code ('C10-12' → 'C'). */
export const sectionOf = (code: string): string => code[0];

