export const VA_ROW_LABELS: Record<string, string> = {
  B2A3G: 'Gross operating surplus & mixed income',
  D1: 'Compensation of employees',
  D21X31: 'Taxes less subsidies on products',
  D29X39: 'Other taxes less subsidies on production',
  OP_RES: 'Purchases by residents abroad',
  OP_NRES: 'Purchases by non-residents in the EU',
};

/** Short display label: prefer the concise curated names, fall back to Eurostat's. */
export function shortLabel(data: FigaroIoData, code: string): string {
  const curated = FINAL_DEMAND_LABELS[code] ?? VA_ROW_LABELS[code];
  if (curated) return curated;
  const raw = data.industries[code] ?? code;
  const cut = raw.split(/[;(]/)[0].trim();
  return cut.length > 60 ? `${cut.slice(0, 59)}…` : cut;
}

/* --------------------------------------------------------------- origin scopes */

export type OriginSelection = 'TOTAL' | 'EU27' | 'EXTRA' | string;

export const ORIGIN_SCOPES: { id: OriginSelection; label: string }[] = [
  { id: 'TOTAL', label: 'All origins (total economy)' },
  { id: 'EU27', label: 'Intra-EU (incl. value added)' },
  { id: 'EXTRA', label: 'Extra-EU imports (all partners)' },
];

/**
 * Resolve an origin selection to a 70×69 matrix (€ million). Sums are cheap
 * (24 × 4 830 additions) — memoise at the call site with useMemo.
 */
export function matrixFor(data: FigaroIoData, year: FigaroYear, origin: OriginSelection): number[][] {
  const byOrigin = data.matrix[year];
  if (origin !== 'TOTAL' && origin !== 'EXTRA') return byOrigin[origin] ?? [];
  const codes = data.origins.filter((o) => (origin === 'EXTRA' ? o !== 'EU27' : true));
  const rows = data.indAva.length;
  const cols = data.indUse.length;
  const out: number[][] = Array.from({ length: rows }, () => new Array(cols).fill(0));
  for (const o of codes) {
    const m = byOrigin[o];
    if (!m) continue;
    for (let r = 0; r < rows; r++) {
      const src = m[r];
      const dst = out[r];
      for (let c = 0; c < cols; c++) dst[c] += src[c];
    }
  }
  return out;
}

/* ------------------------------------------------------------------ formatting */

/** € million → compact € billion string. */
export const fmtBn = (mio: number): string => {
  const bn = mio / 1000;
  const abs = Math.abs(bn);
  if (abs >= 1000) return `${(bn / 1000).toFixed(2)} tn`;
  if (abs >= 100) return `${bn.toFixed(0)} bn`;
  if (abs >= 1) return `${bn.toFixed(1)} bn`;
  if (abs >= 0.05) return `${bn.toFixed(2)} bn`;
  return `${mio.toFixed(0)} m`;
};

export const fmtCell = (mio: number): string => {
  const bn = mio / 1000;
  const abs = Math.abs(bn);
  if (abs >= 100) return bn.toFixed(0);
  if (abs >= 10) return bn.toFixed(1);
  if (abs >= 0.05) return bn.toFixed(2);
  return '·';
};
